function extractCellBlock(content, cellNum) {
  const marker = '// tableCell' + cellNum;
  const start = content.indexOf('\n            ' + marker);
  if (start < 0) return null;
  let searchFrom = start + marker.length + 1;
  let end = content.length;
  const re = /\n            \/\/ tableCell|\n            \/\/ tableRow/;
  const m = content.slice(searchFrom).match(re);
  if (m) {
    end = searchFrom + m.index;
  }
  return content.slice(start + 1, end);
}

const cellBlocks = {};
statCells.forEach(function (c) {
  const b = extractCellBlock(canon, c);
  if (!b) throw new Error('missing canon block tableCell' + c);
  cellBlocks[c] = b;
});

function replaceCellBlock(content, cellNum, newBlock) {
  const marker = '// tableCell' + cellNum;
  const start = content.indexOf('\n            ' + marker);
  if (start < 0) throw new Error('missing target tableCell' + cellNum);
  let searchFrom = start + marker.length + 1;
  let end = content.length;
  const m = content.slice(searchFrom).match(/\n            \/\/ tableCell|\n            \/\/ tableRow/);
  if (m) end = searchFrom + m.index;
  return content.slice(0, start + 1) + newBlock + content.slice(end);
}

function extractFieldBlock(content) {
  const start = content.indexOf('        private DevExpress.XtraReports.Parameters.Parameter RL_XuatSac;');
  const end = content.indexOf('        private DevExpress.XtraReports.Parameters.Parameter pReport_Place;');
  if (start < 0 || end < 0) throw new Error('field block not found in canon');
  return content.slice(start, end);
}

function replaceOldStatFields(content, newFields) {
  const start = content.indexOf('        private DevExpress.XtraReports.Parameters.Parameter pXuatSac;');
  const end = content.indexOf('        private DevExpress.XtraReports.Parameters.Parameter pReport_Place;');
  if (start < 0 || end < 0) throw new Error('old fields not found');
  return content.slice(0, start) + newFields + content.slice(end);
}

function extractInitStatParams(content) {
  const lines = content.split('\n');
  const out = [];
  let capture = false;
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i];
    if (l.indexOf('this.HT_XuatSac = new') >= 0) capture = true;
    if (!capture) continue;
    out.push(l);
    if (l.indexOf('this.HT_TLYeu.Name =') >= 0) {
      capture = false;
      break;
    }
  }
  if (out.length === 0) throw new Error('init block not found canon');
  return out.join('\n') + '\n';
}

